"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.errors import ProjectError
from hourglass.merging import intersect_spans, merge_spans
from hourglass.models import Span


def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def _check_inside(worked: Iterable[Span], hours: Span):
    for span in worked:
        if intersect_spans(span, hours) != span:
            raise ProjectError(f"{span} is outside {hours}")


def _edge_pairs(worked: Iterable[Span], hours: Span):
    edges = [hours.start]
    for span in merge_spans(worked):
        edges += [span.start, span.end]
    edges.append(hours.end)
    return zip(edges[::2], edges[1::2])


# ---
def find_gaps(worked: Iterable[Span], hours: Span) -> List[str]:
    """Labels like "gap 12:00-13:00 (60 min)", one per gap."""
    worked = list(worked)
    _check_inside(worked, hours)
    return [
        f"gap {_clock(a)}-{_clock(b)} ({b - a} min)"
        for a, b in _edge_pairs(worked, hours)
        if a < b
    ]

